#define _XOPEN_SOURCE 700
#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include "fs_runtime.h"
static uint32_t checks;
static void check(int ok,const char*why){checks++;if(!ok){fprintf(stderr,"filesystem check%u: %s\n",checks,why);exit(1);}}
static void word(a0fs_session*s,uint32_t expected){check(a0fs_read(s)==expected,"reply word");}
static void send(a0fs_session*s,uint32_t op,uint32_t n,const uint32_t*a){a0fs_write(s,op);a0fs_write(s,n);for(uint32_t i=0;i<n;i++)a0fs_write(s,a[i]);}
static void response(a0fs_session*s,uint32_t status,uint32_t count,uint32_t*out){word(s,status);word(s,count);for(uint32_t i=0;i<count;i++){uint32_t v=a0fs_read(s);if(out)out[i]=v;}}
static a0fs_session*start(uint32_t budget){a0fs_session*s=a0fs_create(budget,0);check(s!=NULL,"create");word(s,0);word(s,4);word(s,A0_ARENA_MAGIC);word(s,1);word(s,A0_FS_MAGIC);word(s,1);check(!a0fs_is_complete(s),"finish required");return s;}
static void finish(a0fs_session*s){uint32_t code=9;send(s,5,1,&code);response(s,0,0,NULL);check(a0fs_is_complete(s),"finish complete");check(!a0fs_protocol_failed(s),"no protocol fault");check(a0fs_allocated_words(s)==0,"finish releases allocations");uint64_t calls=a0fs_calls(s,19);send(s,19,0,NULL);response(s,5,0,NULL);check(a0fs_calls(s,19)==calls,"finished request does not call OS");check(a0fs_is_complete(s),"complete after finished reply drained");a0fs_destroy(s);}
static uint32_t upload(a0fs_session*s,const unsigned char*p,uint32_t n){uint32_t result[128];send(s,1,1,&n);response(s,0,1,result);uint32_t h=result[0];for(uint32_t i=0;i<n;){uint32_t k=n-i>128?128:n-i,args[131]={h,i,k};for(uint32_t j=0;j<k;j++)args[j+3]=p[i+j];send(s,3,k+3,args);response(s,0,0,NULL);i+=k;}return h;}
static void cell(a0fs_session*s,uint32_t h,uint32_t value){const uint32_t args[]={h,0,1,value};send(s,3,4,args);response(s,0,0,NULL);}
static void files(const char*dir){size_t cap=strlen(dir)+40;char*path=malloc(cap),*missing=malloc(cap);check(path&&missing,"path allocation");check(snprintf(path,cap,"%s/fs-transport.txt",dir)>0,"file path");check(snprintf(missing,cap,"%s/fs-missing.txt",dir)>0,"missing path");const unsigned char contents[]={0,255,10,0};FILE*f=fopen(path,"wb");check(f!=NULL,"create fixture");check(fwrite(contents,1,sizeof contents,f)==sizeof contents,"write fixture");check(fclose(f)==0,"close fixture");uint32_t n=(uint32_t)strlen(path),result[128];a0fs_session*s=start(100000);uint32_t h=upload(s,(const unsigned char*)path,n),args[]={h,0,n};
/* The extension permits an ordinary .txt file: extension/root/source policy is A0. */
send(s,17,3,args);response(s,0,3,result);check(result[0]==0&&result[1]!=0&&result[2]==sizeof contents,"raw file reply");uint32_t load[]={result[1],0,result[2]};send(s,2,3,load);response(s,0,4,result);for(uint32_t i=0;i<4;i++)check(result[i]==contents[i],"raw byte preserved");
send(s,16,3,args);response(s,0,3,result);check(result[0]==0&&result[1]!=0,"realpath reply");char*canonical=realpath(path,NULL);check(canonical!=NULL,"OS realpath oracle");check(result[2]==strlen(canonical),"realpath length");for(uint32_t i=0;i<result[2];){uint32_t k=result[2]-i>128?128:result[2]-i,page[128],a[]={result[1],i,k};send(s,2,3,a);response(s,0,k,page);for(uint32_t j=0;j<k;j++)check(page[j]==(unsigned char)canonical[i+j],"realpath bytes");i+=k;}free(canonical);
send(s,18,3,args);response(s,0,4,result);check(result[0]==0&&S_ISREG(result[1]),"stat raw mode");check(result[2]==4&&result[3]==0,"stat full width size");send(s,19,0,NULL);response(s,0,3,result);char*cwd=getcwd(NULL,0);check(cwd!=NULL,"OS cwd oracle");check(result[0]==0&&result[2]==strlen(cwd),"cwd length");for(uint32_t i=0;i<result[2];){uint32_t k=result[2]-i>128?128:result[2]-i,page[128],a[]={result[1],i,k};send(s,2,3,a);response(s,0,k,page);for(uint32_t j=0;j<k;j++)check(page[j]==(unsigned char)cwd[i+j],"cwd bytes");i+=k;}free(cwd);
uint32_t badhandle[]={UINT32_MAX,0,1};send(s,17,3,badhandle);response(s,2,0,NULL);uint32_t badrange[]={h,UINT32_MAX,2};send(s,17,3,badrange);response(s,3,0,NULL);uint32_t beyond[]={h,n,1};send(s,17,3,beyond);response(s,3,0,NULL);cell(s,h,256);send(s,17,3,args);response(s,3,0,NULL);cell(s,h,0);send(s,17,3,args);response(s,0,3,result);check(result[0]==EINVAL&&result[1]==0&&result[2]==0,"NUL is OS argument error");cell(s,h,(unsigned char)path[0]);send(s,17,3,args);response(s,0,3,result);check(result[0]==0&&result[2]==4,"recoverable errors preserve session");uint32_t mh=upload(s,(const unsigned char*)missing,(uint32_t)strlen(missing)),ma[]={mh,0,(uint32_t)strlen(missing)};send(s,17,3,ma);response(s,0,3,result);check(result[0]==ENOENT&&result[1]==0&&result[2]==0,"OS errno separate from transport");finish(s);
/* Failed output allocation is generic resource4, without a fabricated OS error. */
s=start(n);h=upload(s,(const unsigned char*)path,n);uint32_t limited[]={h,0,n};send(s,17,3,limited);response(s,4,0,NULL);check(!a0fs_protocol_failed(s),"resource failure recoverable");finish(s);check(remove(path)==0,"remove fixture");free(path);free(missing);}
static void faults(void){a0fs_session*s=a0fs_create(256,0);check(s!=NULL,"create undrained");a0fs_write(s,19);const uint32_t initial[]={0,4,A0_ARENA_MAGIC,1,A0_FS_MAGIC,1,1,0};for(uint32_t i=0;i<sizeof initial/sizeof initial[0];i++)word(s,initial[i]);check(a0fs_protocol_failed(s)&&!a0fs_is_complete(s),"undrained hello sticky");a0fs_destroy(s);
s=start(256);a0fs_write(s,16);a0fs_write(s,3);a0fs_write(s,1);word(s,1);word(s,0);check(a0fs_protocol_failed(s)&&a0fs_calls(s,16)==0,"truncated OS request never executes");a0fs_destroy(s);
s=start(256);a0fs_write(s,19);a0fs_write(s,1);word(s,1);word(s,0);check(a0fs_protocol_failed(s)&&a0fs_calls(s,19)==0,"bad OS shape never executes");a0fs_destroy(s);
s=start(256);uint32_t n=128,r[128];send(s,1,1,&n);response(s,0,1,r);uint32_t h=r[0],store[131]={h,0,128};for(uint32_t i=0;i<128;i++)store[i+3]=i+1;send(s,3,131,store);response(s,0,0,NULL);uint32_t load[]={h,0,128};send(s,2,3,load);word(s,0);word(s,128);word(s,1);word(s,2);a0fs_write(s,19);for(uint32_t i=3;i<=128;i++)word(s,i);word(s,1);word(s,0);check(a0fs_protocol_failed(s)&&!a0fs_is_complete(s),"unread largest reply preserved before sticky frame");a0fs_destroy(s);
s=start(256);uint32_t one=1;send(s,1,1,&one);response(s,0,1,r);uint32_t mismatch[]={r[0],0,1};send(s,3,3,mismatch);response(s,1,0,NULL);check(a0fs_protocol_failed(s),"base protocol failure propagated");a0fs_destroy(s);}
int main(int argc,char**argv){check(argc==2,"fixture directory");files(argv[1]);faults();printf("filesystem protocol %u checks passed\n",checks);return 0;}
